WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v), unpacked AS (SELECT id, latency_ms, v, CAST((status_code & 2) != 0 AS INT) AS is_flagged, SHIFTRIGHT(status_code, 2) AS status_code_high FROM flattened WHERE latency_ms = 652), valid AS (SELECT id, latency_ms, v, status_code_high, ROUND(status_code_high * 0.85, 2) AS adjusted_status_code_high, CASE WHEN latency_ms >= 2067 THEN 'High' WHEN latency_ms >= 697 THEN 'Medium' ELSE 'Low' END AS latency_ms_level FROM unpacked WHERE status_code_high > 2), cleaned AS (SELECT id, latency_ms, v, status_code_high, adjusted_status_code_high, latency_ms_level, ROUND(adjusted_status_code_high, 2) AS adjusted_status_code_high_rounded FROM valid WHERE latency_ms >= 1333), metrics AS (SELECT *, RANK() OVER (ORDER BY adjusted_status_code_high_rounded DESC NULLS FIRST) AS adjusted_status_code_high_rounded_rank, CUME_DIST() OVER w_recent AS adjusted_status_code_high_cume_dist, PERCENT_RANK() OVER w_hist AS status_code_high_percent_rank, PERCENT_RANK() OVER w_hist AS status_code_high_percent_rank_2, RANK() OVER w_ordered AS adjusted_status_code_high_rank FROM cleaned WHERE adjusted_status_code_high BETWEEN 62 AND 68 WINDOW w_recent AS (ORDER BY adjusted_status_code_high NULLS LAST), w_hist AS (ORDER BY status_code_high DESC NULLS FIRST), w_ordered AS (ORDER BY adjusted_status_code_high DESC)), cleaned_app_logs AS (SELECT *, CASE WHEN status_code_high >= 2 THEN 'High' WHEN status_code_high >= 1 THEN 'Medium' ELSE 'Low' END AS status_code_high_band FROM metrics WHERE adjusted_status_code_high_rank BETWEEN 4 AND 5) SELECT CASE WHEN adjusted_status_code_high_rounded_rank >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS adjusted_status_code_high_rounded_rank_tier, CASE WHEN status_code_high_percent_rank >= 0.75 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_high_percent_rank_tier, CASE WHEN status_code_high >= 2 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_tier, ROUND(AVG(status_code_high_percent_rank), 2) AS avg_status_code_high_percent_rank, PERCENTILE_APPROX(adjusted_status_code_high_rank, ARRAY(0.25, 0.5, 0.75)) AS adjusted_status_code_high_rank_quartiles FROM cleaned_app_logs GROUP BY CASE WHEN adjusted_status_code_high_rounded_rank >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN status_code_high_percent_rank >= 0.75 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN status_code_high >= 2 THEN 'HIGH' ELSE 'LOW' END
